SET NAMES utf8mb4;
CREATE TABLE admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,name VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(140) NOT NULL UNIQUE,description TEXT,status ENUM('active','hidden') DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE collections (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(140) NOT NULL UNIQUE,description TEXT,image VARCHAR(255),status ENUM('active','hidden') DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE brands (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(140) NOT NULL UNIQUE,tagline VARCHAR(255),description TEXT,logo VARCHAR(255),accent_color VARCHAR(20) DEFAULT '#191919',status ENUM('active','hidden') DEFAULT 'active',featured TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,brand_id INT UNSIGNED NULL,category_id INT UNSIGNED NULL,collection_id INT UNSIGNED NULL,name VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,description TEXT,price DECIMAL(10,2) NOT NULL,sale_price DECIMAL(10,2) NULL,sizes VARCHAR(255),colours VARCHAR(255),stock INT UNSIGNED DEFAULT 0,image VARCHAR(255),status ENUM('active','hidden','draft') DEFAULT 'draft',featured TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(brand_id) REFERENCES brands(id) ON DELETE SET NULL,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,FOREIGN KEY(collection_id) REFERENCES collections(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(40) NOT NULL UNIQUE,customer_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(60),address TEXT NOT NULL,city VARCHAR(120),postal_code VARCHAR(30),country VARCHAR(120),notes TEXT,subtotal DECIMAL(10,2) NOT NULL,shipping DECIMAL(10,2) DEFAULT 0,total DECIMAL(10,2) NOT NULL,payment_method VARCHAR(50) DEFAULT 'order_request',status ENUM('pending','confirmed','processing','shipped','completed','cancelled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE order_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id INT UNSIGNED NOT NULL,product_id INT UNSIGNED NULL,product_name VARCHAR(180) NOT NULL,quantity INT UNSIGNED NOT NULL,unit_price DECIMAL(10,2) NOT NULL,line_total DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE brand_applications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,applicant_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(60),country VARCHAR(120),brand_name VARCHAR(160),story TEXT,target_audience TEXT,preferred_style VARCHAR(255),preferred_products VARCHAR(255),artwork VARCHAR(255),social_links TEXT,budget VARCHAR(120),launch_date DATE NULL,notes TEXT,status ENUM('new','reviewing','accepted','declined') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE contacts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,subject VARCHAR(200),message TEXT NOT NULL,status ENUM('new','read','replied') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE newsletter_subscribers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,status ENUM('active','unsubscribed') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(120) NOT NULL UNIQUE,setting_value TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,name VARCHAR(160) NOT NULL,status ENUM('active','disabled') DEFAULT 'active',stripe_customer_id VARCHAR(80) NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE user_entitlements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,entitlement_key VARCHAR(120) NOT NULL,status ENUM('active','inactive') DEFAULT 'inactive',source_type ENUM('payment','subscription') NOT NULL,source_id VARCHAR(100) NOT NULL,expires_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY user_entitlement(user_id,entitlement_key),KEY entitlement_source(source_type,source_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE stripe_webhook_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(100) NOT NULL UNIQUE,event_type VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;

